for rel_path, b64_data in FILES.items():
    path = pathlib.Path(rel_path)
    path.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64_data)
    path.write_bytes(data)
    print(f"[OK] {rel_path} ({len(data)} bytes)")

